import { createDbFromPool } from "@ogcio/db-core";
import type { Pool } from "pg";
import { describe, expect, it } from "vitest";
import type { DB } from "../../db/schema.js";
import { SharingModel } from "../../models/sharing-model.js";

// These tests exercise the REAL SQL generated by SharingModel through a mocked
// pg pool (no live DB). Kysely acquires a client via `pool.connect()` and runs
// `client.query(sql, params)`; we capture that call to assert both the compiled
// statement and the bound parameters, plus the boolean the finder derives from
// the returned rows.
type QueryCall = { text: string; params: unknown[] };

const normalizeSql = (sql: string): string => sql.replace(/\s+/g, " ").trim();

const buildPoolMock = (rows: unknown[], calls: QueryCall[]): Pool =>
  ({
    connect: () =>
      Promise.resolve({
        query: (text: string, params: unknown[]) => {
          calls.push({ text, params });
          return Promise.resolve({ rows });
        },
        release: () => {},
      }),
  }) as unknown as Pool;

const modelWith = (rows: unknown[], calls: QueryCall[]) =>
  new SharingModel(createDbFromPool<DB>(buildPoolMock(rows, calls)));

describe("SharingModel.isSharedWithUser", () => {
  it("runs the single-user access query and returns true on a match", async () => {
    const calls: QueryCall[] = [];
    const model = modelWith([{ userId: "user-1" }], calls);

    const result = await model.isSharedWithUser("file-1", "user-1");

    expect(result).toBe(true);
    expect(calls).toHaveLength(1);
    expect(normalizeSql(calls[0].text)).toBe(
      "SELECT user_id FROM files_users WHERE file_id = $1 and user_id = $2 LIMIT 1",
    );
    expect(calls[0].params).toEqual(["file-1", "user-1"]);
  });

  it("returns false when no row matches", async () => {
    const calls: QueryCall[] = [];
    const model = modelWith([], calls);

    const result = await model.isSharedWithUser("file-1", "user-1");

    expect(result).toBe(false);
    expect(calls[0].params).toEqual(["file-1", "user-1"]);
  });
});

describe("SharingModel.isSharedWithAnyUser", () => {
  it("runs the ANY(...) query with the user-id array and returns true on a match", async () => {
    const calls: QueryCall[] = [];
    const model = modelWith([{ userId: "child" }], calls);

    const result = await model.isSharedWithAnyUser("file-1", [
      "child",
      "other",
    ]);

    expect(result).toBe(true);
    expect(normalizeSql(calls[0].text)).toBe(
      "SELECT user_id FROM files_users WHERE file_id = $1 and user_id = ANY($2) LIMIT 1",
    );
    // The whole array is bound as a single positional parameter.
    expect(calls[0].params).toEqual(["file-1", ["child", "other"]]);
  });

  it("returns false when no row matches", async () => {
    const calls: QueryCall[] = [];
    const model = modelWith([], calls);

    const result = await model.isSharedWithAnyUser("file-1", []);

    expect(result).toBe(false);
    expect(calls[0].params).toEqual(["file-1", []]);
  });
});
